-- Cost at scale (supabase/migrations/0077_settings_held.sql): docs/plans/2026-11-03-cost-at-scale-plan.md, Task 3.
-- Every key in SETTINGS (engine/rules/instance.ts) is held where it is written: each poison below is refused with 23514 and
-- each good is accepted. engine/rules/settings-held.test.ts reads the two lists (one row per line) and checks them against
-- the TypeScript rules, so the two sides cannot drift. presencePollSeconds = 5 and presenceNames = 0 are the issue's own cases.
-- The economy good is the fixtures' value, not test-world's: the card kinds this database holds each need a price in it (0006).
-- Earlier files commit card kinds of their own (a race needs committed rows), so the economy good is written over the row
-- already there: the good's prices, and the price the database already holds for every other kind.

create temp table poisons (key text, value text);

create temp table goods (key text, value text);

do $$
declare r record; refused boolean; seen integer; first_good text;
begin
  -- Every key has a row to update: the first good of each is written (an insert or an update; the hold accepts it).
  for r in select distinct on (key) key, value from goods order by key, ctid loop
      on conflict (key) do update set value = case when settings.key = 'economy' then settings.value || excluded.value else excluded.value end;
  end loop;

  for r in select * from goods loop
    update settings set value = case when key = 'economy' then value || r.value::jsonb else r.value::jsonb end where key = r.key;
    get diagnostics seen = row_count;
    if seen <> 1 then raise exception '% = % : the good had no row to update', r.key, r.value; end if;
  end loop;

  for r in select * from poisons loop
    refused := false;
    begin
      update settings set value = r.value::jsonb where key = r.key;
    exception when check_violation then
      refused := true;
      -- The database names the predicate that failed: every refusal opens with its key.
      if sqlerrm not like r.key || '%' then raise exception '% = % was refused without naming its key: %', r.key, r.value, sqlerrm; end if;
    end;
    if not refused then raise exception '% = % was not refused with 23514', r.key, r.value; end if;
  end loop;

  -- A refusal names its key.
  begin
    update settings set value = '5' where key = 'presencePollSeconds';
    raise exception 'presencePollSeconds = 5 was not refused';
  exception when check_violation then
    if sqlerrm not like 'presencePollSeconds is %' then raise exception 'a refusal names its key: %', sqlerrm; end if;
  end;
  begin
    update settings set value = '0' where key = 'presenceNames';
    raise exception 'presenceNames = 0 was not refused';
  exception when check_violation then
    if sqlerrm not like 'presenceNames is %' then raise exception 'a refusal names its key: %', sqlerrm; end if;
  end;

  -- The insert path is held as the update path is.
  delete from settings where key = 'presenceNames';
  begin
    raise exception 'an insert of presenceNames = 0 was not refused';
  exception when check_violation then null;
  end;

  -- The two settings the seed writes beside `conduct` (0340) are outside SETTINGS and held all the same: engine/rules/settings-held.test.ts reads only
  -- the two lists above, so theirs are here.
  for r in select * from (values ('conductVersion', '1'), ('conductVersion', '3'), ('conductSections', '[]'), ('conductSections', '["mask", "hate"]')) g(key, value) loop
  end loop;
  for r in select * from (values
    ('conductVersion', '0'), ('conductVersion', '1.5'), ('conductVersion', '"1"'), ('conductVersion', 'null'), ('conductVersion', 'true'), ('conductVersion', '-1'),
    ('conductVersion', '9007199254740992'),
    ('conductSections', '"mask"'), ('conductSections', 'null'), ('conductSections', '{}'), ('conductSections', '[1]'), ('conductSections', '[""]'),
    ('conductSections', '[" "]'), ('conductSections', '["a", null]'), ('conductSections', '[["a"]]')) p(key, value) loop
    refused := false;
    begin
      update settings set value = r.value::jsonb where key = r.key;
    exception when check_violation then
      refused := true;
      if sqlerrm not like r.key || '%' then raise exception '% = % was refused without naming its key: %', r.key, r.value, sqlerrm; end if;
    end;
    if not refused then raise exception '% = % was not refused with 23514', r.key, r.value; end if;
  end loop;

  -- A key outside SETTINGS is no business of the hold, whatever it holds.
  update settings set value = '"anything"' where key = 'notASetting';

  -- The migration's last statement: a row that already broke a rule (written before the hold existed, here past it with the
  -- trigger off) fails the pass of every row through the hold, naming its key.
  alter table settings disable trigger settings_held;
  update settings set value = '5' where key = 'presencePollSeconds';
  alter table settings enable trigger settings_held;
  begin
    update settings set value = value;
    raise exception 'a row already breaking its rule passed the hold';
  exception when check_violation then
    if sqlerrm not like 'presencePollSeconds is %' then raise exception 'the pass names the key that broke: %', sqlerrm; end if;
  end;
end $$;
